&lt;span class="p"&gt;}&lt;/span&gt;

&lt;span class="n"&gt;FORM&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="p"&gt;{&lt;/span&gt;
