&amp;lt;h1&amp;gt;MedSpeak&amp;lt;/h1&amp;gt;
&amp;lt;p class=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;sub&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;Type or scan the shorthand exactly as written on the label — get back plain instructions anyone can follow.&amp;lt;/p&amp;gt;

&amp;lt;div class=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;card&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;
&amp;lt;label class=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;field-label&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt; for=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;rx&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;Prescription text&amp;lt;/label&amp;gt;
&amp;lt;div class=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;row&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;
&amp;lt;input type=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;text&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt; id=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;rx&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt; placeholder=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;e.g. 1 tab BID pc&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt; onkeydown=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;if(event.key===&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;Enter&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;)go()&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;
&amp;lt;button onclick=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;go()&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;Decode&amp;lt;/button&amp;gt;
&amp;lt;/div&amp;gt;
&amp;lt;p class=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;examples&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;Try &amp;lt;code&amp;gt;1 tab BID pc&amp;lt;/code&amp;gt; &amp;amp;middot; &amp;lt;code&amp;gt;PRN q6h&amp;lt;/code&amp;gt; &amp;amp;middot; &amp;lt;code&amp;gt;2 cap TID AC PO&amp;lt;/code&amp;gt;&amp;lt;/p&amp;gt;

&amp;lt;div class=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;label-wrap&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;
&amp;lt;div class=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;rx-label empty&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt; id=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;out&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;
&amp;lt;span class=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;tag&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;Instructions&amp;lt;/span&amp;gt;
Decoded text will appear here.
&amp;lt;/div&amp;gt;
&amp;lt;/div&amp;gt;
&amp;lt;/div&amp;gt;

&amp;lt;div class=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;scan-section&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;
&amp;lt;label class=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;field-label&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;Or scan a photo of the prescription&amp;lt;/label&amp;gt;
&amp;lt;div class=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;upload-box&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;
&amp;lt;input type=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;file&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt; id=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;imgInput&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt; accept=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;image/*&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt; onchange=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;handleImage(event)&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;
&amp;lt;img id=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;preview&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;
&amp;lt;p id=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;scanStatus&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;&amp;lt;/p&amp;gt;
&amp;lt;/div&amp;gt;
&amp;lt;/div&amp;gt;
&amp;lt;/main&amp;gt;

&amp;lt;script&amp;gt;
async function go(){
const text = document.getElementById(&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;rx&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;).value;
const out = document.getElementById(&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;out&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;);
if(!text.trim()){ return; }
const res = await fetch(&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;/api/decode&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;, {
method: &lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;POST&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;,
headers: {&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;Content-Type&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;:&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;application/json&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;},
body: JSON.stringify({text: text})
});
const data = await res.json();
out.classList.remove(&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;empty&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;);
out.innerHTML = &lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;&amp;lt;span class=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;tag&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;&amp;gt;Instructions&amp;lt;/span&amp;gt;&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt; + data.result;
}

function handleImage(event){
const file = event.target.files[0];
if (!file) return;
const preview = document.getElementById(&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;preview&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;);
preview.src = URL.createObjectURL(file);
preview.style.display = &lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;block&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;;
scanImage(file);
}

async function scanImage(file){
const status = document.getElementById(&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;scanStatus&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;);
status.innerText = &lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;Reading text from image...&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;;
try {
const result = await Tesseract.recognize(file, &lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;eng&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;);
const rawText = result.data.text.trim();
status.innerText = rawText ? (&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;Detected: &lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt; + rawText) : &lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;No text found — try a clearer photo.&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;;
if (rawText){
document.getElementById(&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;rx&lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;).value = rawText.replace(/&lt;/span&gt;&lt;span class="se"&gt;\\&lt;/span&gt;&lt;span class="s"&gt;n/g, &lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt; &lt;/span&gt;&lt;span class="sh"&gt;'&lt;/span&gt;&lt;span class="s"&gt;);
go();
}
} catch(e){
status.innerText = &lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;Scan failed — type it manually instead.&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;;
}
}
&amp;lt;/script&amp;gt;
&amp;lt;/body&amp;gt;&amp;lt;/html&amp;gt;
&lt;/span&gt;&lt;span class="sh"&gt;"""&lt;/span&gt;

&lt;span class="k"&gt;class&lt;/span&gt; &lt;span class="nc"&gt;Handler&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="n"&gt;BaseHTTPRequestHandler&lt;/span&gt;&lt;span class="p"&gt;):&lt;/span&gt;
&lt;span class="k"&gt;def&lt;/span&gt; &lt;span class="nf"&gt;_send&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="n"&gt;self&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="n"&gt;code&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="n"&gt;body&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="n"&gt;ctype&lt;/span&gt;&lt;span class="o"&gt;=&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;application/json&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="p"&gt;):&lt;/span&gt;
&lt;span class="n"&gt;self&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;send_response&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="n"&gt;code&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;span class="n"&gt;self&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;send_header&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;Content-Type&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="n"&gt;ctype&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;span class="n"&gt;self&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;end_headers&lt;/span&gt;&lt;span class="p"&gt;()&lt;/span&gt;
&lt;span class="n"&gt;self&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="n"&gt;wfile&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;write&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="n"&gt;body&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;encode&lt;/span&gt;&lt;span class="p"&gt;())&lt;/span&gt;

&lt;span class="k"&gt;def&lt;/span&gt; &lt;span class="nf"&gt;do_GET&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="n"&gt;self&lt;/span&gt;&lt;span class="p"&gt;):&lt;/span&gt;
&lt;span class="k"&gt;if&lt;/span&gt; &lt;span class="n"&gt;self&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="n"&gt;path&lt;/span&gt; &lt;span class="o"&gt;==&lt;/span&gt; &lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;/&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;
&lt;span class="n"&gt;self&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;_send&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="mi"&gt;200&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="n"&gt;HTML_PAGE&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;text/html&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;span class="k"&gt;else&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;
&lt;span class="n"&gt;self&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;_send&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="mi"&gt;404&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;{}&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;

&lt;span class="k"&gt;def&lt;/span&gt; &lt;span class="nf"&gt;do_POST&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="n"&gt;self&lt;/span&gt;&lt;span class="p"&gt;):&lt;/span&gt;
&lt;span class="k"&gt;if&lt;/span&gt; &lt;span class="n"&gt;self&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="n"&gt;path&lt;/span&gt; &lt;span class="o"&gt;==&lt;/span&gt; &lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;/api/decode&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;
&lt;span class="n"&gt;length&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="nf"&gt;int&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="n"&gt;self&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="n"&gt;headers&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;get&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;Content-Length&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;0&lt;/span&gt;&lt;span class="p"&gt;))&lt;/span&gt;
&lt;span class="n"&gt;data&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="n"&gt;json&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;loads&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="n"&gt;self&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="n"&gt;rfile&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;read&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="n"&gt;length&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt; &lt;span class="ow"&gt;or&lt;/span&gt; &lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;{}&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;span class="n"&gt;text&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="n"&gt;data&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;get&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;text&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="sh"&gt;""&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;span class="n"&gt;result&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="nf"&gt;decode&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="n"&gt;text&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;span class="n"&gt;self&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;_send&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="mi"&gt;200&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="n"&gt;json&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;dumps&lt;/span&gt;&lt;span class="p"&gt;({&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;result&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt; &lt;span class="n"&gt;result&lt;/span&gt;&lt;span class="p"&gt;}))&lt;/span&gt;
&lt;span class="k"&gt;else&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;
&lt;span class="n"&gt;self&lt;/span&gt;&lt;span class="p"&gt;.&lt;/span&gt;&lt;span class="nf"&gt;_send&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="mi"&gt;404&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;{}&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;

&lt;span class="k"&gt;def&lt;/span&gt; &lt;span class="nf"&gt;log_message&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="n"&gt;self&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="o"&gt;*&lt;/span&gt;&lt;span class="n"&gt;args&lt;/span&gt;&lt;span class="p"&gt;):&lt;/span&gt;
&lt;span class="k"&gt;pass&lt;/span&gt;

&lt;span class="k"&gt;if&lt;/span&gt; &lt;span class="n"&gt;__name__&lt;/span&gt; &lt;span class="o"&gt;==&lt;/span&gt; &lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;__main__&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt;
&lt;span class="nf"&gt;print&lt;/span&gt;&lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;MedSpeak running at http://localhost:8000&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="p"&gt;)&lt;/span&gt;
&lt;span class="nc"&gt;ThreadingHTTPServer&lt;/span&gt;&lt;span class="p"&gt;((&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="s"&gt;0.0.0.0&lt;/span&gt;&lt;span class="sh"&gt;"&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt; &lt;span class="mi"&gt;8000&lt;/span&gt;&lt;span class="p"&gt;),&lt;/span&gt; &lt;span class="n"&gt;Handler&lt;/span&gt;&lt;span class="p"&gt;).&lt;/span&gt;&lt;span class="nf"&gt;serve_forever&lt;/span&gt;&lt;span class="p"&gt;()&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;Run it with &lt;code&gt;python medspeak.py&lt;/code&gt; and open &lt;code&gt;http://localhost:8000&lt;/code&gt;.&lt;/p&gt;

&lt;h2&gt;


6. Trying it out
&lt;/h2&gt;

&lt;p&gt;Same decoding examples as before, plus the new scan path:&lt;/p&gt;

&lt;div class="table-wrapper-paragraph"&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Input method&lt;/th&gt;
&lt;th&gt;Example&lt;/th&gt;
&lt;th&gt;Output&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;Typed&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1 tab BID pc&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Take 1 tablet twice a day after meals&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Typed&lt;/td&gt;
&lt;td&gt;&lt;code&gt;PRN q6h&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;As needed every 6 hours&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Scanned photo of a label reading &lt;code&gt;2 CAP TID AC PO&lt;/code&gt;
&lt;/td&gt;
&lt;td&gt;(photo)&lt;/td&gt;
&lt;td&gt;Take 2 capsules three times a day before meals by mouth&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;&lt;/div&gt;

&lt;h2&gt;


Wrap-up
&lt;/h2&gt;

&lt;p&gt;The nice thing about doing OCR client-side with Tesseract.js is that no photo of anyone's prescription ever touches the server — recognition happens entirely in the browser tab, and only the recognized text gets sent to &lt;code&gt;/api/decode&lt;/code&gt;. That's a meaningful privacy property for a tool handling medical labels, and it came essentially for free by picking a client-side OCR library instead of a server-side one.&lt;/p&gt;

&lt;p&gt;&lt;em&gt;Note: OCR accuracy varies with photo quality, lighting, and handwriting — always double-check scanned results against the actual label, and consult your pharmacist for anything ambiguous.&lt;/em&gt;&lt;/p&gt;

&lt;p&gt;A few weeks ago I found out our site had a table of contents that rendered for absolutely nobody.&lt;/p&gt;

&lt;p&gt;The code was there. The CSS was there. It had been shipping to production for months. It just never appeared, because the partial looked for &lt;code&gt;h2[id]&lt;/code&gt; and our markdown renderer only ever emitted &lt;code&gt;&amp;lt;a name="..."&amp;gt;&lt;/code&gt; — a legacy anchor, no &lt;code&gt;id&lt;/code&gt; on the heading itself. So the selector matched zero elements, every time, on every article. Nobody noticed because nobody was looking at it.&lt;/p&gt;

&lt;p&gt;I only found it because I was hunting for something else: why our content wasn't getting picked up by AI search — ChatGPT, Perplexity, Google's AI Overviews. We've got ~1,600 published articles. Plenty of traffic historically. And almost nothing showing up as a &lt;em&gt;citation&lt;/em&gt; in any of the answer engines.&lt;/p&gt;

&lt;p&gt;That hunt turned into a couple of weeks of work. Here's what actually mattered, what didn't, and the stuff I got wrong on the way.&lt;/p&gt;

&lt;h2&gt;


The thing nobody tells you: access comes first
&lt;/h2&gt;

&lt;p&gt;I spent a day reading AEO checklists (that's "answer engine optimization" — SEO for the machines that answer instead of link). Every one of them opens with schema markup. None of them start with the question that actually gates everything: &lt;strong&gt;can the AI crawlers even fetch your pages?&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Go look at your &lt;code&gt;robots.txt&lt;/code&gt; right now. The bots that feed the answer engines are &lt;code&gt;GPTBot&lt;/code&gt;, &lt;code&gt;OAI-SearchBot&lt;/code&gt;, &lt;code&gt;ClaudeBot&lt;/code&gt;, &lt;code&gt;PerplexityBot&lt;/code&gt;, &lt;code&gt;Google-Extended&lt;/code&gt;, &lt;code&gt;CCBot&lt;/code&gt;. If any of those are disallowed, everything downstream is theater.&lt;/p&gt;

&lt;p&gt;There's a genuinely nasty gotcha here I didn't know. In the robots protocol, a &lt;em&gt;named&lt;/em&gt; user-agent group &lt;strong&gt;replaces&lt;/strong&gt; the &lt;code&gt;*&lt;/code&gt; group for that bot — it doesn't merge. So if you did the "nice" thing and added &lt;code&gt;User-agent: GPTBot&lt;/code&gt; / &lt;code&gt;Allow: /&lt;/code&gt; blocks, congratulations: those bots now ignore all your &lt;code&gt;*&lt;/code&gt; disallows and happily crawl &lt;code&gt;/reactions&lt;/code&gt;, &lt;code&gt;/admin&lt;/code&gt;, whatever. We had GPTBot burning crawl budget on tracking endpoints for exactly this reason. The fix was to delete all the per-bot groups and keep one &lt;code&gt;User-agent: *&lt;/code&gt; that allows content and blocks only the junk. Everyone, bots included, follows it.&lt;/p&gt;

&lt;p&gt;Then add an &lt;code&gt;llms.txt&lt;/code&gt; — a plain-text, hand-curated list of your best URLs with a one-line description each. It's the "here's what's worth reading" file for models. Cheap to write, and it's becoming a real convention.&lt;/p&gt;

&lt;h2&gt;


Make your paragraphs quotable
&lt;/h2&gt;

&lt;p&gt;This is the part that clicked for me. Answer engines don't cite pages. They cite &lt;em&gt;passages&lt;/em&gt;. And a passage a model can grab cleanly is one that:&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;lives under a heading that answers a real question ("How much VRAM do I need for a 70B model?" not "Requirements"),&lt;/li&gt;
&lt;li&gt;states its answer in the first two sentences, no "as we discussed above,"&lt;/li&gt;
&lt;li&gt;and is small enough to be a chunk on its own (the rough unit is ~500 tokens).&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;Comparison content punches above its weight here, and I think I finally understand why. The rerankers these systems use are good at contrast and negation — "X does this, Y does &lt;em&gt;not&lt;/em&gt;." So a section literally titled "Cursor vs Copilot" with a table underneath is basically pre-chewed for them.&lt;/p&gt;

&lt;p&gt;And — back to my dead table of contents — put &lt;code&gt;id&lt;/code&gt;s on your headings:&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight html"&gt;&lt;code&gt;&lt;span class="c"&gt;&amp;lt;!-- legacy, not enough --&amp;gt;&lt;/span&gt;
&lt;span class="nt"&gt;&amp;lt;h2&amp;gt;&amp;lt;a&lt;/span&gt; &lt;span class="na"&gt;name=&lt;/span&gt;&lt;span class="s"&gt;"vram"&lt;/span&gt;&lt;span class="nt"&gt;&amp;gt;&lt;/span&gt;VRAM&lt;span class="nt"&gt;&amp;lt;/a&amp;gt;&amp;lt;/h2&amp;gt;&lt;/span&gt;

&lt;span class="c"&gt;&amp;lt;!-- what you want --&amp;gt;&lt;/span&gt;
&lt;span class="nt"&gt;&amp;lt;h2&lt;/span&gt; &lt;span class="na"&gt;id=&lt;/span&gt;&lt;span class="s"&gt;"vram"&lt;/span&gt;&lt;span class="nt"&gt;&amp;gt;&lt;/span&gt;VRAM&lt;span class="nt"&gt;&amp;lt;/h2&amp;gt;&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;Fragment-addressable sections (&lt;code&gt;/post#vram&lt;/code&gt;) are easier for a model to isolate and quote. Fixing our renderer was one line. Fixing the &lt;em&gt;existing&lt;/em&gt; 1,600 articles meant re-rendering all of them, because the HTML was stored, not generated on the fly. Don't forget that step — I almost did.&lt;/p&gt;

&lt;h2&gt;


Schema: useful, but not for the reason you think
&lt;/h2&gt;

&lt;p&gt;Yes, emit JSON-LD. But Google killed FAQ rich &lt;em&gt;results&lt;/em&gt; for most sites back in 2023, so if you're doing FAQ schema for the little dropdown in search results, stop — you won't get it. Do it because the answer engines &lt;em&gt;parse&lt;/em&gt; it.&lt;/p&gt;

&lt;p&gt;One bug I'd bet money you have if you generate FAQ schema from markdown: your answer text is full of markdown. A &lt;code&gt;[link](url)&lt;/code&gt; or &lt;code&gt;**bold**&lt;/code&gt; sitting inside &lt;code&gt;acceptedAnswer.text&lt;/code&gt; looks broken to a parser. We were doing exactly this. Strip the syntax before you store it — plain text only.&lt;/p&gt;

&lt;p&gt;The one that I think matters most, though, is the site-level entity graph. An &lt;code&gt;Organization&lt;/code&gt; + &lt;code&gt;WebSite&lt;/code&gt; block, emitted on every page, with a &lt;code&gt;sameAs&lt;/code&gt; array pointing at your real social/profile URLs. It's how you tell these systems "this domain is a coherent entity you can trust as a source." If you do one schema thing, do this one.&lt;/p&gt;

&lt;h2&gt;


The honest part
&lt;/h2&gt;

&lt;p&gt;Here's what I can't tell you: whether any of it worked yet.&lt;/p&gt;

&lt;p&gt;Our Google traffic is still down about 24% over the last month. The AEO changes are days old. Crawlers re-fetch on their own clock, and the answer engines update slowly, so the earliest I'd expect to see movement is a few weeks out. Anyone promising you a before/after in 48 hours is selling something.&lt;/p&gt;

&lt;p&gt;What I &lt;em&gt;can&lt;/em&gt; tell you is the metric to watch, and it's not Google clicks. It's &lt;strong&gt;cited pages&lt;/strong&gt; — how many of your URLs show up as sources inside ChatGPT / Perplexity / AI Overviews. Some tools report this now. That number is the one that responds to this work. Track it every couple of weeks, ignore the daily noise.&lt;/p&gt;

&lt;p&gt;So that's the playbook: let the crawlers in, make your paragraphs stand on their own, describe your entity consistently, and measure the right thing. Most of it is unglamorous. The table of contents that rendered for nobody is a decent metaphor for the whole exercise — half of AEO is just fixing the quiet stuff you assumed already worked.&lt;/p&gt;

&lt;p&gt;&lt;em&gt;I run &lt;a href="https://promptzone.com" rel="noopener noreferrer"&gt;PromptZone&lt;/a&gt;, a community for prompt engineering and AI builders. Everything above came out of doing this to our own corpus.&lt;/em&gt;&lt;/p&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;Originally published at &lt;a href="https://blog.pathvector.dev/protocol-lab-mss-37/" rel="noopener noreferrer"&gt;https://blog.pathvector.dev/protocol-lab-mss-37/&lt;/a&gt; — part of the free &lt;a href="https://github.com/pathvector-studio/protocol-lab" rel="noopener noreferrer"&gt;Protocol Lab&lt;/a&gt; series.&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;

&lt;p&gt;This post is part of &lt;strong&gt;Protocol Lab&lt;/strong&gt;, a free, hands-on series for learning networking protocols by building and breaking them in a container lab. All the lab material — topologies, configs, and scripts — lives in the repo: &lt;a href="https://github.com/pathvector-studio/protocol-lab" rel="noopener noreferrer"&gt;github.com/pathvector-studio/protocol-lab&lt;/a&gt;.&lt;/p&gt;

&lt;p&gt;In Lab #25, we watched Path MTU Discovery find a smaller link via ICMP — and saw how it black-holes when that ICMP is filtered. This lab is the operational fix: &lt;strong&gt;MSS clamping&lt;/strong&gt;. A router on the path rewrites the &lt;strong&gt;MSS&lt;/strong&gt; in passing TCP SYNs so both endpoints agree, up front, to send segments that fit the narrowest link — no reliance on PMTUD working.&lt;/p&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;Reading guide:&lt;/strong&gt; &lt;a href="https://github.com/pathvector-studio/protocol-lab/blob/main/rfc-notes/mss-clamping.md" rel="noopener noreferrer"&gt;rfc-notes/mss-clamping.md&lt;/a&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Prerequisite:&lt;/strong&gt; &lt;a href="https://github.com/pathvector-studio/protocol-lab/blob/main/labs/mtu-25-path-mtu-discovery.md" rel="noopener noreferrer"&gt;Lab 25: MTU and Path MTU Discovery&lt;/a&gt;&lt;/p&gt;
&lt;/blockquote&gt;

&lt;p&gt;Expected time: 35–50 minutes.&lt;/p&gt;

&lt;h2&gt;


The Goal
&lt;/h2&gt;

&lt;p&gt;The client's link is MTU 1500; the r–server link is MTU &lt;strong&gt;1400&lt;/strong&gt;:&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;
&lt;strong&gt;Without clamping&lt;/strong&gt;, the client's SYN advertises &lt;strong&gt;MSS 1460&lt;/strong&gt; (its local 1500 − 40); a full segment is too big for the 1400 link and depends on PMTUD.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;With clamping&lt;/strong&gt;, &lt;code&gt;r&lt;/code&gt; rewrites the SYN's MSS down to &lt;strong&gt;1360&lt;/strong&gt; (1400 − 40), so both ends send segments that always fit.&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;By the end, you should be able to explain this table:&lt;/p&gt;

&lt;div class="table-wrapper-paragraph"&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;&lt;/th&gt;
&lt;th&gt;SYN MSS seen at the server&lt;/th&gt;
&lt;th&gt;why&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;without clamping&lt;/td&gt;
&lt;td&gt;1460&lt;/td&gt;
&lt;td&gt;client's local MTU 1500 − 40&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;with clamping&lt;/td&gt;
&lt;td&gt;1360&lt;/td&gt;
&lt;td&gt;
&lt;code&gt;r&lt;/code&gt; clamps to the 1400-MTU link (− 40)&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;&lt;/div&gt;

&lt;h2&gt;


What You Will Learn
&lt;/h2&gt;

&lt;ul&gt;
&lt;li&gt;What the TCP &lt;strong&gt;MSS&lt;/strong&gt; option is and how endpoints derive it from local MTU.&lt;/li&gt;
&lt;li&gt;Why the SYN MSS is &lt;strong&gt;blind&lt;/strong&gt; to a smaller link deeper in the path.&lt;/li&gt;
&lt;li&gt;How &lt;strong&gt;PMTUD&lt;/strong&gt; can &lt;strong&gt;blackhole&lt;/strong&gt; when ICMP is filtered (recap of Lab 25).&lt;/li&gt;
&lt;li&gt;How &lt;strong&gt;MSS clamping&lt;/strong&gt; on a router rewrites the SYN's MSS to fit the path.&lt;/li&gt;
&lt;li&gt;Why this matters for tunnels (WireGuard/VXLAN/GRE) that shrink the effective MTU.&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;This lab does &lt;strong&gt;not&lt;/strong&gt; cover:&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;Full PMTUD internals (Lab 25 covers those).&lt;/li&gt;
&lt;li&gt;IPv6 MSS specifics (MSS = MTU − 60 with the larger minimum).&lt;/li&gt;
&lt;li&gt;Per-route MTU pinning or PLPMTUD (RFC 8899).&lt;/li&gt;
&lt;/ul&gt;

&lt;h2&gt;


Where to Read in the RFCs
&lt;/h2&gt;

&lt;div class="table-wrapper-paragraph"&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Reference&lt;/th&gt;
&lt;th&gt;What to focus on&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;RFC 9293 §3.7.1&lt;/td&gt;
&lt;td&gt;The MSS option and how segment size is decided&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;RFC 1191&lt;/td&gt;
&lt;td&gt;PMTUD (the mechanism clamping backstops)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;RFC 2923&lt;/td&gt;
&lt;td&gt;The PMTUD blackhole problem&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;RFC 5737 / RFC 1918&lt;/td&gt;
&lt;td&gt;Confirming the addresses used here are local-only&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;&lt;/div&gt;

&lt;h2&gt;


The Big Picture
&lt;/h2&gt;

&lt;p&gt;&lt;code&gt;r&lt;/code&gt; sits between the client and the server, and only the r–server link is MTU 1400.&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight plaintext"&gt;&lt;code&gt; client ---- eth1/eth1 ---- r ---- eth2/eth1 ---- server
MTU 1500                       MTU 1400 (narrow)   MTU 1400
SYN: mss 1460  ---&amp;gt;  r clamps ---&amp;gt;  mss 1360 at server
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;In &lt;code&gt;r&lt;/code&gt;'s FORWARD chain (mangle table), we clamp the SYN's MSS to the PMTU.&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight plaintext"&gt;&lt;code&gt;flowchart LR
C["client (MTU 1500)&amp;lt;br/&amp;gt;SYN mss 1460"] --&amp;gt; R["r&amp;lt;br/&amp;gt;TCPMSS --clamp-mss-to-pmtu"]
R --&amp;gt;|"SYN rewritten&amp;lt;br/&amp;gt;mss 1360"| S["server (MTU 1400)"]
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;&lt;code&gt;10.0.0.0/8&lt;/code&gt; is a local, closed range.&lt;/p&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;Note:&lt;/strong&gt; Everything here uses local/documentation address space (RFC 1918 / RFC 5737), so nothing in this lab touches the real internet.&lt;/p&gt;
&lt;/blockquote&gt;

&lt;h2&gt;


What You Need
&lt;/h2&gt;

&lt;p&gt;Recommended environment:&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;Linux / WSL2 / a Linux VM&lt;/li&gt;
&lt;li&gt;Docker&lt;/li&gt;
&lt;li&gt;containerlab&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;Images used:&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;
&lt;code&gt;nicolaka/netshoot:latest&lt;/code&gt; — bundles &lt;code&gt;iptables&lt;/code&gt;, &lt;code&gt;tcpdump&lt;/code&gt;, &lt;code&gt;curl&lt;/code&gt;, and &lt;code&gt;python3&lt;/code&gt;.&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;No additional images are required.&lt;/p&gt;

&lt;h2&gt;


Running the Lab
&lt;/h2&gt;

&lt;p&gt;The quick path, which deploys, verifies, and tears down for you:&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight shell"&gt;&lt;code&gt;./scripts/labctl.sh run mss-37
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;Or step through it manually:&lt;/p&gt;

&lt;h3&gt;


1. Move into the working directory
&lt;/h3&gt;



&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight shell"&gt;&lt;code&gt;&lt;span class="nb"&gt;cd &lt;/span&gt;protocol-lab/examples/mss-37
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;h3&gt;


2. Deploy and start an HTTP server
&lt;/h3&gt;



&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight shell"&gt;&lt;code&gt;&lt;span class="nb"&gt;sudo &lt;/span&gt;containerlab deploy &lt;span class="nt"&gt;-t&lt;/span&gt; mss-37.clab.yml
docker &lt;span class="nb"&gt;exec&lt;/span&gt; &lt;span class="nt"&gt;-d&lt;/span&gt; clab-mss-37-server python3 &lt;span class="nt"&gt;-m&lt;/span&gt; http.server 80
docker &lt;span class="nb"&gt;exec &lt;/span&gt;clab-mss-37-r ip &lt;span class="nt"&gt;-br&lt;/span&gt; &lt;span class="nb"&gt;link &lt;/span&gt;show eth2   &lt;span class="c"&gt;# mtu 1400&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;h3&gt;


3. Watch the SYN's MSS without clamping
&lt;/h3&gt;



&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight shell"&gt;&lt;code&gt;docker &lt;span class="nb"&gt;exec&lt;/span&gt; &lt;span class="nt"&gt;-d&lt;/span&gt; clab-mss-37-server sh &lt;span class="nt"&gt;-c&lt;/span&gt; &lt;span class="s1"&gt;'tcpdump -i eth1 -n -c1 "tcp[tcpflags] &amp;amp; tcp-syn != 0 and tcp[tcpflags] &amp;amp; tcp-ack == 0" &amp;gt; /tmp/syn.txt 2&amp;gt;&amp;amp;1'&lt;/span&gt;
docker &lt;span class="nb"&gt;exec &lt;/span&gt;clab-mss-37-client curl &lt;span class="nt"&gt;-s&lt;/span&gt; &lt;span class="nt"&gt;--max-time&lt;/span&gt; 4 http://10.0.8.2/ &lt;span class="o"&gt;&amp;gt;&lt;/span&gt;/dev/null
docker &lt;span class="nb"&gt;exec &lt;/span&gt;clab-mss-37-server &lt;span class="nb"&gt;grep&lt;/span&gt; &lt;span class="nt"&gt;-oE&lt;/span&gt; &lt;span class="s1"&gt;'mss [0-9]+'&lt;/span&gt; /tmp/syn.txt
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;You should see &lt;code&gt;mss 1460&lt;/code&gt; — the client's local 1500 − 40.&lt;/p&gt;

&lt;h3&gt;


4. Enable MSS clamping on r
&lt;/h3&gt;



&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight shell"&gt;&lt;code&gt;docker &lt;span class="nb"&gt;exec &lt;/span&gt;clab-mss-37-r iptables &lt;span class="nt"&gt;-t&lt;/span&gt; mangle &lt;span class="nt"&gt;-A&lt;/span&gt; FORWARD &lt;span class="nt"&gt;-p&lt;/span&gt; tcp &lt;span class="nt"&gt;--tcp-flags&lt;/span&gt; SYN,RST SYN &lt;span class="nt"&gt;-j&lt;/span&gt; TCPMSS &lt;span class="nt"&gt;--clamp-mss-to-pmtu&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;h3&gt;


5. Watch the SYN's MSS again
&lt;/h3&gt;



&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight shell"&gt;&lt;code&gt;docker &lt;span class="nb"&gt;exec&lt;/span&gt; &lt;span class="nt"&gt;-d&lt;/span&gt; clab-mss-37-server sh &lt;span class="nt"&gt;-c&lt;/span&gt; &lt;span class="s1"&gt;'tcpdump -i eth1 -n -c1 "tcp[tcpflags] &amp;amp; tcp-syn != 0 and tcp[tcpflags] &amp;amp; tcp-ack == 0" &amp;gt; /tmp/syn2.txt 2&amp;gt;&amp;amp;1'&lt;/span&gt;
docker &lt;span class="nb"&gt;exec &lt;/span&gt;clab-mss-37-client curl &lt;span class="nt"&gt;-s&lt;/span&gt; &lt;span class="nt"&gt;--max-time&lt;/span&gt; 4 http://10.0.8.2/ &lt;span class="o"&gt;&amp;gt;&lt;/span&gt;/dev/null
docker &lt;span class="nb"&gt;exec &lt;/span&gt;clab-mss-37-server &lt;span class="nb"&gt;grep&lt;/span&gt; &lt;span class="nt"&gt;-oE&lt;/span&gt; &lt;span class="s1"&gt;'mss [0-9]+'&lt;/span&gt; /tmp/syn2.txt
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;Now it's &lt;code&gt;mss 1360&lt;/code&gt; — &lt;code&gt;r&lt;/code&gt; clamped it to 1400 − 40.&lt;/p&gt;

&lt;h2&gt;


Expected Output
&lt;/h2&gt;

&lt;ul&gt;
&lt;li&gt;
&lt;code&gt;r&lt;/code&gt;'s eth2: &lt;code&gt;mtu 1400&lt;/code&gt;.&lt;/li&gt;
&lt;li&gt;Without clamping: the server sees the SYN carrying &lt;code&gt;mss 1460&lt;/code&gt;.&lt;/li&gt;
&lt;li&gt;With clamping: the server sees &lt;code&gt;mss 1360&lt;/code&gt;.&lt;/li&gt;
&lt;li&gt;The mangle FORWARD chain shows a &lt;code&gt;TCPMSS clamp to PMTU&lt;/code&gt; rule.&lt;/li&gt;
&lt;/ul&gt;

&lt;h2&gt;


Why It Works
&lt;/h2&gt;

&lt;p&gt;MSS clamping is "tell both endpoints a safe segment size at the start, instead of relying on PMTUD."&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;
&lt;strong&gt;MSS.&lt;/strong&gt; The maximum payload TCP will accept in one segment. It is advertised &lt;strong&gt;only in the SYN&lt;/strong&gt;, and the value is &lt;strong&gt;local MTU − 40&lt;/strong&gt; (IPv4): MTU 1500 → 1460. The sender caps its segments at the peer's advertised MSS.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;The blind spot.&lt;/strong&gt; Each endpoint only knows its own interface MTU. Even if a narrower link sits deeper in the path (here, the 1400-MTU r–server link), the SYN's MSS doesn't reflect it.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;PMTUD and blackholes&lt;/strong&gt; (Lab 25). When an oversized segment with DF set hits the narrow link, the router returns an ICMP "fragmentation needed" and the sender shrinks. But if that ICMP is filtered, the sender never learns; large segments keep getting dropped and the connection hangs — a &lt;strong&gt;blackhole&lt;/strong&gt;.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;Clamping.&lt;/strong&gt; A router on the path rewrites the &lt;strong&gt;MSS option in passing SYNs&lt;/strong&gt; down to the outgoing link's MTU − 40 (if the advertised value is larger). In this lab, &lt;code&gt;r&lt;/code&gt; lowers 1460 → 1360. Both ends then send at 1360 or below, so segments always fit the 1400 link — no blackhole even when PMTUD is broken. Rewriting only the SYN is sufficient, because MSS is negotiated only in the SYN.&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;The key insight: &lt;strong&gt;a router on the path injects the path's minimum MTU — invisible to the endpoints — into the SYN's MSS, so both ends send fitting segments from the very first byte.&lt;/strong&gt; It's a staple in real deployments where tunnels shrink the effective MTU.&lt;/p&gt;

&lt;h2&gt;


Common Pitfalls
&lt;/h2&gt;

&lt;ul&gt;
&lt;li&gt;
&lt;strong&gt;Confusing MSS with MTU.&lt;/strong&gt; MTU is the whole IP packet; MSS is the TCP payload. In IPv4, MSS = MTU − 40.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;Thinking MSS is renegotiated.&lt;/strong&gt; It's negotiated only in the SYN, not per data segment — which is exactly why rewriting the SYN's MSS option is all it takes.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;Assuming PMTUD is enough.&lt;/strong&gt; ICMP filtering can blackhole it. Clamping is the insurance.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;Assuming you can just lower the endpoint's MTU.&lt;/strong&gt; The narrow link deep in the path is invisible from the endpoint. It's the &lt;strong&gt;router on the path&lt;/strong&gt; that has to do the rewrite.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;Expecting it to help UDP.&lt;/strong&gt; MSS is a TCP concept; UDP is a different problem.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;The clamp value.&lt;/strong&gt; &lt;code&gt;--clamp-mss-to-pmtu&lt;/code&gt; derives from the outgoing MTU; use &lt;code&gt;--set-mss&lt;/code&gt; for a fixed value.&lt;/li&gt;
&lt;/ul&gt;

&lt;h2&gt;


Cleanup
&lt;/h2&gt;



&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight shell"&gt;&lt;code&gt;&lt;span class="nb"&gt;sudo &lt;/span&gt;containerlab destroy &lt;span class="nt"&gt;-t&lt;/span&gt; mss-37.clab.yml &lt;span class="nt"&gt;--cleanup&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;If you used &lt;code&gt;labctl.sh run mss-37&lt;/code&gt;, the script runs &lt;code&gt;destroy&lt;/code&gt; for you at the end.&lt;/p&gt;

&lt;h2&gt;


Check Your Understanding
&lt;/h2&gt;

&lt;ol&gt;
&lt;li&gt;What is TCP MSS? How does it differ from MTU (what's the IPv4 relationship)?&lt;/li&gt;
&lt;li&gt;When is the MSS negotiated? Can it change outside the SYN?&lt;/li&gt;
&lt;li&gt;Why can't the SYN's MSS reflect a narrower link deeper in the path?&lt;/li&gt;
&lt;li&gt;When does PMTUD blackhole?&lt;/li&gt;
&lt;li&gt;What does MSS clamping rewrite, and where? Why does 1460 become 1360 in this lab?&lt;/li&gt;
&lt;li&gt;Why is clamping so valued with tunnels (WireGuard/VXLAN/GRE)?&lt;/li&gt;
&lt;/ol&gt;

&lt;h2&gt;


References
&lt;/h2&gt;

&lt;ul&gt;
&lt;li&gt;&lt;a href="https://www.rfc-editor.org/rfc/rfc9293" rel="noopener noreferrer"&gt;RFC 9293: Transmission Control Protocol&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href="https://www.rfc-editor.org/rfc/rfc1191" rel="noopener noreferrer"&gt;RFC 1191: Path MTU Discovery&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href="https://www.rfc-editor.org/rfc/rfc2923" rel="noopener noreferrer"&gt;RFC 2923: TCP Problems with Path MTU Discovery&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href="https://www.rfc-editor.org/rfc/rfc5737" rel="noopener noreferrer"&gt;RFC 5737: IPv4 Address Blocks Reserved for Documentation&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;h2&gt;


Verified Run Log (2026-07-07)
&lt;/h2&gt;

&lt;p&gt;This lab has been confirmed reproducible on real hardware.&lt;/p&gt;

&lt;p&gt;Environment:&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;Ubuntu 26.04 LTS (kernel 7.0.0-27-generic, x86_64)&lt;/li&gt;
&lt;li&gt;Docker 29.1.3&lt;/li&gt;
&lt;li&gt;containerlab 0.77.0&lt;/li&gt;
&lt;li&gt;client / r / server: &lt;code&gt;nicolaka/netshoot:latest&lt;/code&gt; (&lt;code&gt;iptables&lt;/code&gt;, &lt;code&gt;tcpdump&lt;/code&gt;, &lt;code&gt;curl&lt;/code&gt;, &lt;code&gt;python3&lt;/code&gt;)&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;Running &lt;code&gt;PATH="/tmp/pl-shim:$PATH" ./scripts/labctl.sh run mss-37&lt;/code&gt; performed deploy → verify → destroy, and &lt;code&gt;verification.json&lt;/code&gt; returned &lt;code&gt;"status": "verified"&lt;/code&gt;.&lt;/p&gt;

&lt;h3&gt;


Without clamping → the SYN carries MSS 1460
&lt;/h3&gt;

&lt;p&gt;Capturing the client's SYN on the server's eth1:&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight plaintext"&gt;&lt;code&gt;Flags [S], seq ..., options [mss 1460, ...]
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;That's &lt;strong&gt;MSS 1460&lt;/strong&gt;, derived from the client's link MTU of 1500 — too big for the r–server link (MTU 1400), leaving the connection dependent on PMTUD.&lt;/p&gt;

&lt;h3&gt;


With clamping on r → the SYN carries MSS 1360
&lt;/h3&gt;



&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight plaintext"&gt;&lt;code&gt;mangle FORWARD: TCPMSS  tcp  flags:0x06/0x02  TCPMSS clamp to PMTU
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;After adding &lt;code&gt;iptables -t mangle -A FORWARD -p tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu&lt;/code&gt;, the same client SYN captured at the server shows:&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight plaintext"&gt;&lt;code&gt;mss 1360
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;&lt;code&gt;r&lt;/code&gt; rewrote the SYN's MSS option from &lt;strong&gt;1460 → 1360&lt;/strong&gt; (1400 − 40) to match its outgoing link (eth2, MTU 1400). From then on both ends send segments of 1360 bytes or less, so everything fits the narrow link — no blackhole, even if ICMP is filtered.&lt;/p&gt;

&lt;div class="table-wrapper-paragraph"&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;&lt;/th&gt;
&lt;th&gt;SYN MSS seen at the server&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;without clamping&lt;/td&gt;
&lt;td&gt;1460&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;with clamping&lt;/td&gt;
&lt;td&gt;1360&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;&lt;/div&gt;

&lt;h3&gt;


Cleanup
&lt;/h3&gt;



&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight shell"&gt;&lt;code&gt;containerlab destroy &lt;span class="nt"&gt;-t&lt;/span&gt; mss-37.clab.yml &lt;span class="nt"&gt;--cleanup&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;






&lt;p&gt;That's MSS clamping: one iptables rule on the path router, and every TCP connection agrees on a safe segment size before the first byte of data — no working PMTUD required.&lt;/p&gt;

&lt;p&gt;Explore the full &lt;strong&gt;Protocol Lab&lt;/strong&gt; series here: &lt;a href="https://github.com/pathvector-studio/protocol-lab" rel="noopener noreferrer"&gt;github.com/pathvector-studio/protocol-lab&lt;/a&gt;. If these labs are useful to you, please ⭐ &lt;strong&gt;star the repo on GitHub&lt;/strong&gt; — it genuinely helps others find the project.&lt;/p&gt;

&lt;p&gt;Next up, we'll keep digging into how real networks stay reliable when the textbook mechanisms fail.&lt;/p&gt;

&lt;p&gt;Since the middle of April 2026 I have published 67 posts on dev.to. My best one has 576 views. That is not a humble brag, it is the honest ceiling of a security developer who decided to write in public and hit publish every day for three months. I want to lay out what actually happened, with the real numbers I have, because most "how to blog" advice comes from people who skip the unglamorous middle.&lt;/p&gt;

&lt;h2&gt;


The number that surprised me
&lt;/h2&gt;

&lt;p&gt;My top performer is a practical Ollama guide. A how-to. Run this model locally, here is the command, here is the gotcha on WSL2. 576 views.&lt;/p&gt;

&lt;p&gt;Meanwhile the posts I was proudest of, the deep smart contract security pieces where I actually know things most people do not, consistently pulled roughly a fifth of the traffic. Not once. As a pattern. The local-AI how-tos beat the deep security content something like five to one on views, over and over.&lt;/p&gt;

&lt;p&gt;That stung a little, and then it taught me something. My expertise is not what most readers came for. They came for a Tuesday problem: "I want to run a model on my machine without paying for tokens and it is not working." I happen to be able to answer that clearly. The fact that I would rather talk about reentrancy is my preference, not the reader's need.&lt;/p&gt;

&lt;h2&gt;


Lesson one: write for the reader's Tuesday problem
&lt;/h2&gt;

&lt;p&gt;The security posts assume you already care about smart contract security. That is a small room. The Ollama post assumes you have a laptop and a mild frustration, which is basically everyone in the building.&lt;/p&gt;

&lt;p&gt;I did not stop writing security content. I write it because it is who I am and it is the work I want. But I stopped expecting it to travel. Content that solves a concrete, common, right-now problem travels. Content that requires you to already be in the niche does not, no matter how good it is.&lt;/p&gt;

&lt;h2&gt;


Lesson two: niche expertise needs a bridge topic
&lt;/h2&gt;

&lt;p&gt;Here is the move that started to work. Instead of choosing between "the thing people search for" and "the thing I know deeply," I bridge them. A post like "running a local model to triage code smells" sits on top of the popular Ollama topic but carries my security angle inside it. The Ollama part is the door. The security part is the room I actually wanted to show you.&lt;/p&gt;

&lt;p&gt;That reframes the whole strategy. The popular topic is not a distraction from my expertise, it is the delivery vehicle for it. Nobody clicks "advanced oracle manipulation patterns." Plenty click "cheap local AI setup," and if I can teach one security idea while they are there, that is a win that would never have happened in a pure security post.&lt;/p&gt;

&lt;h2&gt;


Lesson three: nobody comments until you ask
&lt;/h2&gt;

&lt;p&gt;For a long stretch I got near-zero comments. Views, sometimes reactions, but silence. I assumed that was just how it goes for technical writing.&lt;/p&gt;

&lt;p&gt;Then I started ending every post with one genuine question. Not "let me know what you think," which is noise. A specific question tied to the post: what is your default when a stranger sends you a repo, do you write invariants before you read code, that kind of thing. Comments started showing up. Not a flood, but real ones, from people with opinions.&lt;/p&gt;

&lt;p&gt;The lesson is dumb in hindsight. A blog post is a monologue unless you explicitly hand the reader the mic. People will engage if you give them a small, concrete, low-effort opening. A big open-ended "thoughts?" is too much work to answer. A pointed question is easy to answer, so people do.&lt;/p&gt;

&lt;h2&gt;


Lesson four: constancy beats motivation, so automate it
&lt;/h2&gt;

&lt;p&gt;I publish daily, and I do not rely on feeling like it. I have a queue of drafts and a cron script that publishes the next one. The decision "should I post today" is where most blogging dies, so I deleted the decision.&lt;/p&gt;

&lt;p&gt;The setup is not fancy. Drafts live in a folder, a script picks the next one and pushes it via the dev.to API, and cron runs it on a schedule. Roughly:&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight shell"&gt;&lt;code&gt;&lt;span class="c"&gt;#!/usr/bin/env bash&lt;/span&gt;
&lt;span class="nb"&gt;set&lt;/span&gt; &lt;span class="nt"&gt;-euo&lt;/span&gt; pipefail

&lt;span class="nv"&gt;POSTS_DIR&lt;/span&gt;&lt;span class="o"&gt;=&lt;/span&gt;&lt;span class="s2"&gt;"&lt;/span&gt;&lt;span class="nv"&gt;$HOME&lt;/span&gt;&lt;span class="s2"&gt;/projects/pavelEspitia.github.io/posts"&lt;/span&gt;
&lt;span class="nv"&gt;NEXT&lt;/span&gt;&lt;span class="o"&gt;=&lt;/span&gt;&lt;span class="si"&gt;$(&lt;/span&gt;find &lt;span class="s2"&gt;"&lt;/span&gt;&lt;span class="nv"&gt;$POSTS_DIR&lt;/span&gt;&lt;span class="s2"&gt;"&lt;/span&gt; &lt;span class="nt"&gt;-name&lt;/span&gt; &lt;span class="s1"&gt;'*.md'&lt;/span&gt; &lt;span class="nt"&gt;-not&lt;/span&gt; &lt;span class="nt"&gt;-name&lt;/span&gt; &lt;span class="s1"&gt;'.*'&lt;/span&gt; | &lt;span class="nb"&gt;sort&lt;/span&gt; | &lt;span class="nb"&gt;head&lt;/span&gt; &lt;span class="nt"&gt;-n1&lt;/span&gt;&lt;span class="si"&gt;)&lt;/span&gt;

&lt;span class="o"&gt;[&lt;/span&gt; &lt;span class="nt"&gt;-z&lt;/span&gt; &lt;span class="s2"&gt;"&lt;/span&gt;&lt;span class="nv"&gt;$NEXT&lt;/span&gt;&lt;span class="s2"&gt;"&lt;/span&gt; &lt;span class="o"&gt;]&lt;/span&gt; &lt;span class="o"&gt;&amp;amp;&amp;amp;&lt;/span&gt; &lt;span class="o"&gt;{&lt;/span&gt; &lt;span class="nb"&gt;echo&lt;/span&gt; &lt;span class="s2"&gt;"queue empty"&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt; &lt;span class="nb"&gt;exit &lt;/span&gt;0&lt;span class="p"&gt;;&lt;/span&gt; &lt;span class="o"&gt;}&lt;/span&gt;

&lt;span class="c"&gt;# publish $NEXT via the dev.to API, then move it out of the queue&lt;/span&gt;
publish_to_devto &lt;span class="s2"&gt;"&lt;/span&gt;&lt;span class="nv"&gt;$NEXT&lt;/span&gt;&lt;span class="s2"&gt;"&lt;/span&gt; &lt;span class="o"&gt;&amp;amp;&amp;amp;&lt;/span&gt; &lt;span class="nb"&gt;mv&lt;/span&gt; &lt;span class="s2"&gt;"&lt;/span&gt;&lt;span class="nv"&gt;$NEXT&lt;/span&gt;&lt;span class="s2"&gt;"&lt;/span&gt; &lt;span class="s2"&gt;"&lt;/span&gt;&lt;span class="nv"&gt;$POSTS_DIR&lt;/span&gt;&lt;span class="s2"&gt;/published/"&lt;/span&gt;
&lt;span class="nb"&gt;echo&lt;/span&gt; &lt;span class="s2"&gt;"published: &lt;/span&gt;&lt;span class="nv"&gt;$NEXT&lt;/span&gt;&lt;span class="s2"&gt;"&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;





&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight plaintext"&gt;&lt;code&gt;# one post a day at 9am, pulled from the queue
0 9 * * * /home/pavel/projects/pavelEspitia.github.io/publish-next.sh
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;The point is not the code. The point is that motivation is a terrible scheduler. A queue plus automation means I write in batches when I have energy, and publishing happens whether or not today-me feels inspired. Three months of daily posts did not come from discipline. They came from removing the daily choice.&lt;/p&gt;

&lt;h2&gt;


Lesson five: distribution beats polish
&lt;/h2&gt;

&lt;p&gt;I spent real time polishing early posts. Rewriting sentences, agonizing over structure. Those are not my top posts. My top posts are the ones on topics people actually search for, published consistently, cross-posted to more than one platform. The polish barely moved the numbers. The topic and the consistency moved the numbers.&lt;/p&gt;

&lt;p&gt;That does not mean write badly. It means the marginal hour is better spent on "is this a thing people are looking for" and "did I actually ship it to where they are" than on the fourth pass of a sentence nobody will notice. Clear and published beats perfect and queued.&lt;/p&gt;

&lt;h2&gt;


What I would tell myself in April
&lt;/h2&gt;

&lt;p&gt;Write for the problem someone has on a normal Tuesday. Use the popular topic as the door to the room where your real expertise lives. End with a real question so the thing becomes a conversation. Put publishing on a script so your mood is not in charge. And accept that your favorite posts and your most-read posts will often be different posts, and that is fine.&lt;/p&gt;

&lt;p&gt;Sixty-seven posts in, the compounding is subtle but real. Not viral, not a huge following, but a body of work that exists, a habit that runs on rails, and a much clearer sense of what readers actually want from me versus what I assumed they wanted.&lt;/p&gt;

&lt;p&gt;If you write technical posts: what topic of yours quietly outperforms the stuff you are proudest of, and have you leaned into it or fought it?&lt;/p&gt;

&lt;p&gt;I've rebuilt the same Figma design in React by hand more times than I'd like to admit — squinting at the inspector panel, copying hex codes, nudging padding by 2px until it &lt;em&gt;finally&lt;/em&gt; matched the mockup. So while building &lt;a href="https://genvibe.pro" rel="noopener noreferrer"&gt;GenVibe&lt;/a&gt;, I went deep on every way to turn a Figma file into real code.&lt;/p&gt;

&lt;p&gt;Here's everything I learned: what actually works in 2026, what still doesn't, and the workflow I now use to go from a Figma frame to a running app in about 15 minutes — for React, React Native, &lt;em&gt;and&lt;/em&gt; plain HTML.&lt;/p&gt;

&lt;h2&gt;


Why "Figma to code" is suddenly a solved problem
&lt;/h2&gt;

&lt;p&gt;Three things changed between 2024 and 2026 that made automated Figma-to-code workable for real production use:&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;
&lt;strong&gt;Figma's REST API exposes auto-layout, variants, and design tokens.&lt;/strong&gt; AI tools no longer have to infer flexbox from pixel coordinates — they read the source of truth directly.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;Modern LLMs understand component composition.&lt;/strong&gt; Instead of dumping one giant &lt;code&gt;&amp;lt;div&amp;gt;&lt;/code&gt; tree, AI now extracts reusable components, hoists shared styles, and matches your project's naming conventions.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;Browser sandboxes let you preview the output instantly.&lt;/strong&gt; Tools now spin up a container in the browser so you can run the generated code and iterate by chatting, not by re-exporting.&lt;/li&gt;
&lt;/ul&gt;

&lt;h2&gt;


The four ways to convert Figma to code
&lt;/h2&gt;

&lt;h3&gt;


1. Manual rebuild (the old way)
&lt;/h3&gt;

&lt;p&gt;A developer opens Figma, inspects each frame, copies hex codes and spacing into Tailwind classes, and rebuilds the layout component by component. Quality is high but slow — typically 4–8 hours per screen for a polished result. Use this only when the design uses interactions or animations that no tool understands yet.&lt;/p&gt;

&lt;h3&gt;


2. Figma plugins (Anima, Locofy, Builder.io)
&lt;/h3&gt;

&lt;p&gt;Install a plugin inside Figma and click "Export to React." The output is usually a single page with inline styles and absolute positioning — fine for landing pages, painful for production apps. You get speed but lose component reusability.&lt;/p&gt;

&lt;h3&gt;


3. AI app builders with Figma import (GenVibe, Lovable)
&lt;/h3&gt;

&lt;p&gt;The newer category. Connect Figma, paste a frame URL, and an AI agent reads the file, generates a clean React or React Native project, and runs it live in the browser. You iterate by typing "move the CTA button below the hero" or "make the cards stack on mobile" — no manual edits needed.&lt;/p&gt;

&lt;p&gt;GenVibe supports both React and React Native output from a single Figma frame, and the Figma importer ships in the free tier — no credit card required to start. (Lovable focuses on web/PWA output rather than native mobile.)&lt;/p&gt;

&lt;h3&gt;


4. Design-to-code APIs (custom pipelines)
&lt;/h3&gt;

&lt;p&gt;Large engineering teams sometimes script the Figma REST API directly — fetching frame data, mapping component sets to internal design-system primitives, and emitting MDX or JSX. High control, high maintenance. Worth it only if you have a full-time design-systems team.&lt;/p&gt;

&lt;h2&gt;


The workflow I recommend: Figma → GenVibe → Production
&lt;/h2&gt;

&lt;p&gt;Here's the workflow I use to ship Figma designs as working code in under 15 minutes. The same flow works for landing pages, full apps, and React Native mobile screens.&lt;/p&gt;

&lt;h3&gt;


Step 1 — Prep the Figma file
&lt;/h3&gt;

&lt;p&gt;AI tools read your file structure literally, so naming matters. Before importing, do three quick cleanups:&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;
&lt;strong&gt;Use auto-layout&lt;/strong&gt; on every frame that should be responsive. Absolute positioning gets converted to fixed-pixel CSS, which breaks on mobile.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;Name your components.&lt;/strong&gt; A frame called &lt;code&gt;Frame 421&lt;/code&gt; becomes a generic &lt;code&gt;Frame421&lt;/code&gt; component. Renaming it to &lt;code&gt;PricingCard&lt;/code&gt; gives you readable output.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;Define text and color styles.&lt;/strong&gt; Figma styles become design tokens (CSS variables, Tailwind theme keys) in the generated code — much cleaner than 47 hard-coded hex values.&lt;/li&gt;
&lt;/ul&gt;

&lt;h3&gt;


Step 2 — Connect Figma
&lt;/h3&gt;

&lt;p&gt;In GenVibe, open &lt;strong&gt;Settings → Applications&lt;/strong&gt; and click &lt;strong&gt;Connect Figma&lt;/strong&gt;. It's a standard OAuth flow with read-only access to files you own. Once connected, you can import any frame straight into the chat.&lt;/p&gt;

&lt;h3&gt;


Step 3 — Convert a frame
&lt;/h3&gt;

&lt;p&gt;Open the Figma import, paste your frame URL, and pick the frames you want:&lt;/p&gt;

&lt;blockquote&gt;
&lt;p&gt;"Convert this Figma frame to a React + Tailwind component. Use shadcn/ui where possible and make it responsive."&lt;/p&gt;

&lt;p&gt;&lt;code&gt;https://www.figma.com/file/xyz/Pricing-Page?node-id=12:345&lt;/code&gt;&lt;/p&gt;
&lt;/blockquote&gt;

&lt;p&gt;GenVibe pulls the frame, generates a React component with proper auto-layout-to-flexbox conversion, and renders it in the live preview within seconds.&lt;/p&gt;

&lt;h3&gt;


Step 4 — Iterate by chatting
&lt;/h3&gt;

&lt;p&gt;Don't spend time fixing things manually. Type follow-ups instead: "Stack the columns on mobile," "Use my brand colors from &lt;code&gt;tailwind.config.js&lt;/code&gt;," "Extract the badge into its own component." The AI applies changes and you see them live.&lt;/p&gt;

&lt;h3&gt;


Step 5 — Export or deploy
&lt;/h3&gt;

&lt;p&gt;When the screen is right, click &lt;strong&gt;Download Zip&lt;/strong&gt; to grab the source, or &lt;strong&gt;Deploy&lt;/strong&gt; to push it live in one click. The exported project is just clean React with Tailwind — no proprietary runtime, no vendor lock-in.&lt;/p&gt;

&lt;h2&gt;


Figma to React Native: the mobile workflow
&lt;/h2&gt;

&lt;p&gt;React Native is where AI builders differ. Some (Lovable, v0.dev) output web React only, while others (Bolt.new, Replit Agent, GenVibe) can also scaffold React Native + Expo. With GenVibe, when you import a Figma frame you can pick the output target:&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;
&lt;strong&gt;React Web&lt;/strong&gt; — emits &lt;code&gt;.tsx&lt;/code&gt; with Tailwind and React Router.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;React Native + Expo&lt;/strong&gt; — emits &lt;code&gt;.tsx&lt;/code&gt; with &lt;code&gt;StyleSheet.create&lt;/code&gt;, &lt;code&gt;FlatList&lt;/code&gt; instead of &lt;code&gt;map&lt;/code&gt; + &lt;code&gt;div&lt;/code&gt;, and Expo Router for navigation.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;Plain HTML/CSS&lt;/strong&gt; — for static landing pages and email templates.&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;The React Native target understands platform conventions: it uses &lt;code&gt;Pressable&lt;/code&gt; for buttons, &lt;code&gt;SafeAreaView&lt;/code&gt; for top-level layouts, and replaces web-only CSS like &lt;code&gt;grid-template&lt;/code&gt; with flexbox-based layouts (since React Native doesn't support CSS Grid).&lt;/p&gt;

&lt;h3&gt;


Which Figma-to-code tools actually support React Native?
&lt;/h3&gt;

&lt;p&gt;Most design-to-code tools stop at web React. If you need a real iOS/Android app from your Figma file, the field narrows sharply:&lt;/p&gt;

&lt;ul&gt;
&lt;li&gt;
&lt;strong&gt;GenVibe&lt;/strong&gt; — React &lt;em&gt;and&lt;/em&gt; React Native + Expo from the &lt;em&gt;same&lt;/em&gt; Figma frame, run live in the browser, free to start.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;Locofy&lt;/strong&gt; — supports React Native, but as a Figma plugin export: no chat iteration and no in-browser run.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;Builder.io Visual Copilot&lt;/strong&gt; — partial React Native support, plugin-based.&lt;/li&gt;
&lt;li&gt;
&lt;strong&gt;Lovable, Anima, v0.dev&lt;/strong&gt; — web React / HTML only; no native mobile output.&lt;/li&gt;
&lt;/ul&gt;

&lt;h2&gt;


Common Figma-to-code pitfalls (and how to avoid them)
&lt;/h2&gt;

&lt;div class="table-wrapper-paragraph"&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Pitfall&lt;/th&gt;
&lt;th&gt;What goes wrong&lt;/th&gt;
&lt;th&gt;Fix&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;Absolute positioning everywhere&lt;/td&gt;
&lt;td&gt;Mobile breakpoints destroy the layout&lt;/td&gt;
&lt;td&gt;Convert frames to auto-layout before import&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Inconsistent naming&lt;/td&gt;
&lt;td&gt;You get &lt;code&gt;Group4&lt;/code&gt;, &lt;code&gt;Rectangle12&lt;/code&gt; as component names&lt;/td&gt;
&lt;td&gt;Rename layers to semantic names (Hero, Card, Footer)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;No text/color styles&lt;/td&gt;
&lt;td&gt;Generated code has hard-coded hex values everywhere&lt;/td&gt;
&lt;td&gt;Define Figma styles first, link them to your theme&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Detached components&lt;/td&gt;
&lt;td&gt;The same button gets generated 12 times instead of once&lt;/td&gt;
&lt;td&gt;Use Figma component instances, not copied groups&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Raster images for icons&lt;/td&gt;
&lt;td&gt;Generated code embeds PNGs instead of SVGs&lt;/td&gt;
&lt;td&gt;Use vector icon libraries inside Figma&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;&lt;/div&gt;

&lt;h2&gt;


Best Figma-to-code tools in 2026, compared (React &amp;amp; React Native)
&lt;/h2&gt;

&lt;p&gt;Only GenVibe and Locofy reach React Native from a Figma frame; only GenVibe adds live in-browser preview and chat iteration on the free tier.&lt;/p&gt;

&lt;div class="table-wrapper-paragraph"&gt;&lt;table&gt;
